      (* [comment removed for export] *)
      Lemma tail_msusp : forall msF1 mo1 m st ps sz tot (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (p' : Z),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 0xf8a88) fc1 None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz tot -> psI ps tot -> tot <= 0x7ffffffe -> frm0 fc1 ->
        rsp r = spw -> rs1 r = spw -> rs0 r = Z_to_bv 64 (bv_unsigned sp) -> rs2 r = Z_to_bv 64 (sh8 ff) ->
        rgp r = gp -> rtp r = tp -> ra0 r = a0 ->
        ra1 r = Z_to_bv 64 p' -> q0 <= p' <= e ->
        rra r = Z_to_bv 64 0x108358 ->
        pesc_spent H (ps_vs ps0) (e - q0) (lb_bytes (blocks_vs (ps_vs ps))) (as_AL H st0) (as_AL H st) ->
